def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_reqs = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if budget <= 0:
        return 0.0

    total_players = 1 + len(alive_opponents)
    total_req = WATER_REQ
    for r in opp_reqs:
        total_req += r

    supply_ratio = 1.0
    if total_req > 0:
        supply_ratio = float(supply) / float(total_req)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / float(len(prev_bids))) if prev_bids else 0.0

    if supply <= 16:
        market_pressure = 'tight'
    elif supply >= 22:
        market_pressure = 'loose'
    else:
        market_pressure = 'mid'

    urgent = (hp <= 3) or (no_water_days >= 2)
    semi_urgent = (hp <= 5) or (no_water_days >= 1)

    if not alive_opponents:
        if urgent:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    if urgent:
        base = max(DAILY_SALARY * 0.95, highest_prev + 2.5, avg_prev + 3.0)
    elif market_pressure == 'tight' or supply_ratio < 0.34:
        base = max(DAILY_SALARY * 1.08, highest_prev + 1.2, avg_prev + 2.0)
    elif market_pressure == 'mid' or supply_ratio < 0.42:
        base = max(DAILY_SALARY * 0.98, highest_prev + 0.8, avg_prev + 1.0)
    else:
        if semi_urgent:
            base = max(DAILY_SALARY * 0.82, avg_prev)
        else:
            base = DAILY_SALARY * 0.58

    if day >= 8 and hp > 5 and no_water_days == 0 and market_pressure == 'loose':
        base *= 0.9

    if budget < DAILY_SALARY * 1.2 and not urgent:
        base = min(base, DAILY_SALARY * 0.85)

    bid = min(float(budget), float(base))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    my_hp = my_status.get('hp', 0)
    my_budget = my_status.get('budget', 0)

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday traces
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how competitive the market is from the top yesterday bid
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid depends on how much supply likely exists today
    # If supply is higher, we can bid a bit less; if lower, bid more.
    # Ensure indices are integers even if any derived list index is used.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = 0.0 if supply_norm < 0.0 else (1.0 if supply_norm > 1.0 else supply_norm)

    # Target fraction of daily salary
    # Lower supply -> higher fraction; higher supply -> lower fraction.
    base_frac = 0.62 - 0.18 * supply_norm

    # Pressure adjustment from yesterday's highest bid
    # If someone was willing to spend a lot, we increase to avoid losing water.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure_frac = 0.78
    elif highest_prev_bid >= DAILY_SALARY * 0.60:
        pressure_frac = 0.70
    elif highest_prev_bid >= DAILY_SALARY * 0.35:
        pressure_frac = 0.64
    else:
        pressure_frac = 0.58

    # HP urgency
    if my_hp <= 1:
        hp_frac = 0.95
    elif my_hp <= 2:
        hp_frac = 0.88
    elif my_hp <= 3:
        hp_frac = 0.78
    else:
        hp_frac = base_frac

    frac = max(hp_frac, pressure_frac)

    # Budget safety: don't overbid beyond what we can afford
    bid = my_budget * frac

    # Also cap relative to daily salary to avoid rapid depletion
    cap = DAILY_SALARY * 0.85 if my_hp <= 3 else DAILY_SALARY * 0.65
    bid = min(bid, cap)

    # If budget is tiny, just spend what we can
    if my_budget <= 1.0:
        return float(max(0.0, my_budget))

    # Keep bid non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)
